// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (POST /assistant/memories)
	RememberContext(w http.ResponseWriter, r *http.Request, params RememberContextParams)

	// (GET /assistant/turns)
	ListAssistantTurns(w http.ResponseWriter, r *http.Request)

	// (POST /assistant/turns)
	SendAssistantMessage(w http.ResponseWriter, r *http.Request, params SendAssistantMessageParams)

	// (GET /calendar)
	GetCalendar(w http.ResponseWriter, r *http.Request)

	// (GET /calendar/callback)
	CalendarCallback(w http.ResponseWriter, r *http.Request, params CalendarCallbackParams)
	// ConnectCalendar Google の同意画面の URL を返す
	// (POST /calendar/connect)
	ConnectCalendar(w http.ResponseWriter, r *http.Request, params ConnectCalendarParams)

	// (POST /calendar/disconnect)
	DisconnectCalendar(w http.ResponseWriter, r *http.Request, params DisconnectCalendarParams)
	// SyncCalendar Google カレンダーの変更を今すぐ取り込む
	// (POST /calendar/sync)
	SyncCalendar(w http.ResponseWriter, r *http.Request, params SyncCalendarParams)

	// (POST /calendar/webhook)
	CalendarWebhook(w http.ResponseWriter, r *http.Request, params CalendarWebhookParams)
	// GetCompanionLine 場面に合わせた相棒の一言を返す。AI が使えないときは決まった文を返す
	// (POST /companion/lines)
	GetCompanionLine(w http.ResponseWriter, r *http.Request, params GetCompanionLineParams)

	// (GET /config)
	GetConfig(w http.ResponseWriter, r *http.Request)
	// AddSampleTasks デモモードで、課題がないときにサンプルの課題を3件追加する
	// (POST /demo/sample)
	AddSampleTasks(w http.ResponseWriter, r *http.Request, params AddSampleTasksParams)

	// (GET /events)
	SubscribeEvents(w http.ResponseWriter, r *http.Request, params SubscribeEventsParams)
	// IssueExtensionToken デモモードで、拡張が同じデモ利用者として接続するためのトークンを発行する
	// (POST /extension/token)
	IssueExtensionToken(w http.ResponseWriter, r *http.Request, params IssueExtensionTokenParams)

	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)

	// (POST /internal/calendar/renew)
	RenewCalendarChannels(w http.ResponseWriter, r *http.Request)

	// (POST /internal/outbox/{jobId})
	RunOutboxJob(w http.ResponseWriter, r *http.Request, jobId Id)

	// (GET /profile)
	GetProfile(w http.ResponseWriter, r *http.Request)

	// (PUT /profile)
	UpdateProfile(w http.ResponseWriter, r *http.Request, params UpdateProfileParams)

	// (GET /records)
	GetRecords(w http.ResponseWriter, r *http.Request)
	// AdjustDraft 確認中の変更案を、指示に従って AI で調整する。保存はしない
	// (POST /reschedule/adjust)
	AdjustDraft(w http.ResponseWriter, r *http.Request, params AdjustDraftParams)

	// (POST /reschedule/commit)
	CommitDraft(w http.ResponseWriter, r *http.Request, params CommitDraftParams)

	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)

	// (PUT /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request, params UpdateSettingsParams)

	// (GET /shortcut)
	GetShortcut(w http.ResponseWriter, r *http.Request)

	// (DELETE /shortcut/key)
	RevokeShortcutKey(w http.ResponseWriter, r *http.Request, params RevokeShortcutKeyParams)

	// (POST /shortcut/key)
	IssueShortcutKey(w http.ResponseWriter, r *http.Request, params IssueShortcutKeyParams)

	// (POST /shortcut/open)
	OpenFromShortcut(w http.ResponseWriter, r *http.Request)

	// (DELETE /sleep)
	ClearSleep(w http.ResponseWriter, r *http.Request, params ClearSleepParams)

	// (GET /sleep)
	GetSleep(w http.ResponseWriter, r *http.Request)

	// (PUT /sleep)
	UpdateSleep(w http.ResponseWriter, r *http.Request, params UpdateSleepParams)

	// (POST /sleep/morning)
	SettleMorning(w http.ResponseWriter, r *http.Request, params SettleMorningParams)

	// (GET /tasks)
	ListTasks(w http.ResponseWriter, r *http.Request)

	// (POST /tasks)
	CreateTask(w http.ResponseWriter, r *http.Request, params CreateTaskParams)
	// ExtractTasks 自由な文章から課題の候補を AI で取り出す。保存はしない
	// (POST /tasks/extract)
	ExtractTasks(w http.ResponseWriter, r *http.Request, params ExtractTasksParams)
	// PreviewNewTask 新しい課題を登録した場合の計画を計算する。保存はしない
	// (POST /tasks/preview)
	PreviewNewTask(w http.ResponseWriter, r *http.Request, params PreviewNewTaskParams)

	// (DELETE /tasks/{taskId})
	DeleteTask(w http.ResponseWriter, r *http.Request, taskId TaskId, params DeleteTaskParams)

	// (GET /tasks/{taskId})
	GetTask(w http.ResponseWriter, r *http.Request, taskId TaskId)

	// (PUT /tasks/{taskId})
	UpdateTask(w http.ResponseWriter, r *http.Request, taskId TaskId, params UpdateTaskParams)

	// (POST /tasks/{taskId}/complete)
	CompleteTask(w http.ResponseWriter, r *http.Request, taskId TaskId, params CompleteTaskParams)
	// PreviewTaskEdit 課題の内容を変更した場合の、変更前後の計画を計算する。保存はしない
	// (POST /tasks/{taskId}/edit-preview)
	PreviewTaskEdit(w http.ResponseWriter, r *http.Request, taskId TaskId, params PreviewTaskEditParams)

	// (GET /tasks/{taskId}/reschedule)
	GetRescheduleDraft(w http.ResponseWriter, r *http.Request, taskId TaskId, params GetRescheduleDraftParams)

	// (POST /tasks/{taskId}/start)
	StartTask(w http.ResponseWriter, r *http.Request, taskId TaskId, params StartTaskParams)

	// (GET /viewing)
	GetViewing(w http.ResponseWriter, r *http.Request)

	// (POST /viewing/reports)
	ReportViewing(w http.ResponseWriter, r *http.Request, params ReportViewingParams)

	// (POST /viewing/sessions)
	StartViewing(w http.ResponseWriter, r *http.Request, params StartViewingParams)

	// (POST /viewing/sessions/{sessionId}/end)
	EndViewing(w http.ResponseWriter, r *http.Request, sessionId Id, params EndViewingParams)

	// (GET /wallet)
	GetWallet(w http.ResponseWriter, r *http.Request)

	// (GET /wallet/ledger)
	ListLedger(w http.ResponseWriter, r *http.Request, params ListLedgerParams)

	// (PUT /wallet/policy)
	UpdateTimePolicy(w http.ResponseWriter, r *http.Request, params UpdateTimePolicyParams)

	// (GET /work-session)
	GetWorkSession(w http.ResponseWriter, r *http.Request)

	// (POST /work-session/confirm)
	ConfirmWork(w http.ResponseWriter, r *http.Request, params ConfirmWorkParams)

	// (POST /work-session/pause)
	PauseWork(w http.ResponseWriter, r *http.Request, params PauseWorkParams)

	// (POST /work-session/resume)
	ResumeWork(w http.ResponseWriter, r *http.Request, params ResumeWorkParams)
}

